#include <cuda_runtime.h>

// Deliberate out-of-bounds access: the validation must detect this control.
__global__ void invalid_write (int* values)
{
    values[64] = 1;
}

int main ()
{
    int* values = nullptr;
    if (cudaMalloc(&values, sizeof(int)) != cudaSuccess) { return 2; }
    invalid_write<<<1, 1>>>(values);
    cudaDeviceSynchronize();
    cudaFree(values);
    return 0;
}

